    question:
      "54歳女性。再発転移性乳がんに対する化学療法としてドセタキセル・シクロホスファミド療法（4コース）を外来通院で行っている。2コース目で手指のしびれと痛みを訴えたため、牛車腎気丸エキス顆粒とブシ末の処方が追加された。\n\n（追加処方）\n牛車腎気丸エキス顆粒 1回2.5 g（1日7.5 g）\nブシ末 1回0.5 g（1日1.5 g）\n1日3回 朝昼夕食前 14日分\n\nこの追加処方において副作用の主な原因となる生薬は、日本薬局方に収載されている。この生薬に関する記述のうち、正しいのはどれか。2つ選べ。",

