      "68歳男性。肝細胞がんによる肝部分切除後に痛みが出現したため疼痛治療を開始した。1ヶ月前から医療用麻薬が導入され、2週間前に増量された。今回、肝細胞がん再発の治療のため入院となった。緩和ケアチームの薬剤師は、患者へのインタビューにより、「痛みのコントロールは良好だが、2週間ほど前から眠気が強くなり昼間でも傾眠傾向あり」との情報を得た。現在の処方：モルヒネ硫酸塩水和物徐放錠10 mg 1回2錠（1日4錠）1日2回 8時、20時 7日分。モルヒネ塩酸塩内用液5 mg 1回1包 疼痛時 5回分（全5包）。酸化マグネシウム錠330 mg 1回2錠（1日6錠）1日3回 朝昼夕食後 7日分。検査データ：NH3 50 μg/dL、Alb 3.0 g/dL、Na 137 mEq/L、Cl 104 mEq/L、K 5.3 mEq/L、Ca 8.7 mg/dL、BUN 25 mg/dL、Cr 1.28 mg/dL、Ccr 38.2 mL/min、腹水（－）、脳への転移（－）。",
