    field: "法規",
    hasImage: true,
    image: "/pharmacy/103/practical/q315.png",

    question:
      "この調剤を行った保険薬局は、健康保険制度に基づいて調剤報酬を請求できる。次の図は、一般的な調剤報酬の請求、審査、支払いの仕組みであり、①から⑤までは、次の用語のいずれかが当てはまる。\n・一部負担金等の支払い\n・審査済の請求書送付\n・調剤報酬の支払い\n・調剤報酬の請求\n・保険料の支払い\nこの図において、「調剤報酬の請求」はどれか。1つ選べ。",

