      "腎機能不全に対する配慮が必要な患者に高カロリー輸液の調製を行う際、ブドウ糖含有率50%の基本輸液500 mL、脂肪乳剤（ダイズ油20%）100 mL、高カロリー輸液用微量元素製剤（2 mL）、総合ビタミン剤（5 mL）を準備した。この組成に加える総窒素量8.1 mg/mLの総合アミノ酸輸液の量として最も近いのはどれか。1つ選べ。\nただし、NPC/N 比を400、脂肪乳剤（ダイズ油20%）100 mLに含まれる熱量を200 kcalとする。",

