    question:
      "注射液A（pH 3.4、2 mL/アンプル）、注射液B（pH 8.6、2 mL/アンプル）及び注射液C（pH 9.1、10 mL/アンプル）をシリンジ内で混合する。\n\n薬剤師は各注射液のpH変動スケール（上図）に基づいて薬剤の調製を検討した。\n\n混合の可否及び順序として最も適切なのはどれか。1つ選べ。",

